const s = $getWorkflowStaticData('global');

s.seen = s.seen && typeof s.seen === 'object' ? s.seen : {};
s.recentAlerts = Array.isArray(s.recentAlerts) ? s.recentAlerts : [];

const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;
const ACCEPTED_TTL = 30 * DAY;
const NON_ACCEPTED_TTL = 24 * 60 * 60 * 1000;
const ALERT_TTL = 7 * DAY;
const MIN_SCORE = 80;

const officialExchangeDomains = ['binance.com','okx.com','coinbase.com','kraken.com'];
const questDomains = ['galxe.com','layer3.xyz','zealy.io'];
const reputableMediaDomains = ['coindesk.com','decrypt.co','theblock.co'];
const shortenerDomains = ['bit.ly','tinyurl.com','t.co','cutt.ly','shorturl.at'];

const opportunityWords = [
  'airdrop','giveaway','launchpool','launchpad','learn-to-earn',
  'learn and earn','quest','testnet','reward','rewards','campaign','whitelist','allowlist'
];

const scamWords = [
  'seed phrase','recovery phrase','private key','send funds first',
  'double your','guaranteed profit','guaranteed return','remote access',
  'screen share','send crypto to','pay fee to claim','deposit to claim'
];

function str(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  try { return JSON.stringify(v); } catch { return ''; }
}

function host(url) {
  try { return new URL(String(url)).hostname.toLowerCase().replace(/^www\./,''); }
  catch { return ''; }
}

function matches(h, domains) {
  return domains.some(d => h === d || h.endsWith('.' + d));
}

function categoryOf(text) {
  if (/whitelist|allowlist/.test(text)) return 'Whitelist';
  if (/giveaway/.test(text)) return 'Giveaway';
  if (/learn-to-earn|learn and earn|\blearn\b/.test(text)) return 'Learn';
  if (/quest|galxe|layer3|zealy/.test(text)) return 'Quest';
  return 'Airdrop';
}

function uniq(items) {
  const out = [];
  const used = new Set();
  for (const item of items) {
    const k = String(item.link || item.title || '').toLowerCase();
    if (!k || used.has(k)) continue;
    used.add(k);
    out.push(item);
  }
  return out;
}

const input = $input.all();
const accepted = [];

let invalidCount = 0;
let staleCount = 0;
let duplicateCount = 0;
let scamRejectedCount = 0;
let belowThresholdCount = 0;
let sourceErrorCount = 0;
let officialSourceCount = 0;

for (const item of input) {
  const x = item.json || {};

  if (x.error || x.errorMessage) {
    sourceErrorCount++;
    continue;
  }

  const title = str(x.title).trim();
  const link = str(x.link).trim();
  if (!title || !link) {
    invalidCount++;
    continue;
  }

  const sourceObj = x.source && typeof x.source === 'object' ? x.source : null;
  const sourceName = sourceObj
    ? str(sourceObj.title || sourceObj.name).trim()
    : str(x.source).trim();
  const sourceUrl = sourceObj ? str(sourceObj.url).trim() : '';
  const sourceHost = host(sourceUrl);
  const linkHost = host(link);

  const textBlob = [
    title,
    sourceName,
    str(x.content),
    str(x.contentSnippet),
    str(x.creator),
    str(x.author)
  ].filter(Boolean).join(' ').toLowerCase();

  const dedupeKey = link.toLowerCase();
  const prev = s.seen[dedupeKey];
  if (prev && typeof prev === 'object') {
    const ttl = prev.accepted ? ACCEPTED_TTL : NON_ACCEPTED_TTL;
    if (Number(prev.at) && now - Number(prev.at) < ttl) {
      duplicateCount++;
      continue;
    }
  }

  const publishedRaw = x.isoDate || x.pubDate || x.published || '';
  const published = Date.parse(publishedRaw);
  if (Number.isFinite(published) && now - published > 7 * DAY) {
    staleCount++;
    s.seen[dedupeKey] = { at: now, accepted: false, score: 0 };
    continue;
  }

  let score = 20;
  let sourceVerification = 'UNVERIFIED';
  const scoreReasons = [];
  const riskFlags = [];

  if (matches(sourceHost, officialExchangeDomains)) {
    score += 55;
    sourceVerification = 'OFFICIAL_EXCHANGE';
    scoreReasons.push('Publisher domain matches a supported official exchange.');
    officialSourceCount++;
  } else if (matches(sourceHost, questDomains)) {
    score += 50;
    sourceVerification = 'KNOWN_QUEST_PLATFORM';
    scoreReasons.push('Publisher domain matches a supported quest platform.');
  } else if (matches(sourceHost, reputableMediaDomains)) {
    score += 30;
    sourceVerification = 'REPUTABLE_MEDIA';
    scoreReasons.push('Publisher domain matches a supported crypto media source.');
  } else {
    const lowerSource = sourceName.toLowerCase();
    if (officialExchangeDomains.some(d => lowerSource.includes(d.split('.')[0]))) {
      score += 25;
      sourceVerification = 'EXCHANGE_MENTION';
      scoreReasons.push('Official exchange is mentioned, but publisher domain is not confirmed as official.');
    } else if (questDomains.some(d => lowerSource.includes(d.split('.')[0]))) {
      score += 20;
      sourceVerification = 'QUEST_MENTION';
      scoreReasons.push('Known quest platform is mentioned, but publisher domain is not confirmed.');
    } else if (reputableMediaDomains.some(d => lowerSource.includes(d.split('.')[0]))) {
      score += 15;
      sourceVerification = 'MEDIA_MENTION';
      scoreReasons.push('Known media brand is mentioned, but publisher domain is not confirmed.');
    }
  }

  if (opportunityWords.some(v => textBlob.includes(v))) {
    score += 20;
    scoreReasons.push('Opportunity keywords detected.');
  }

  if (/\bfree\b|no cost|zero cost|learn/.test(textBlob)) {
    score += 5;
    scoreReasons.push('Low/no-cost wording detected.');
  }

  if (/deadline|ends|until|eligible|eligibility|claim/.test(textBlob)) {
    score += 5;
    scoreReasons.push('Eligibility/deadline/claim wording detected.');
  }

  if (/connect wallet|wallet connection|sign message/.test(textBlob)) {
    score -= 5;
    riskFlags.push('Wallet connection or signing may be requested.');
  }

  if (matches(linkHost, shortenerDomains)) {
    score -= 15;
    riskFlags.push('Shortened link detected.');
  }

  const scamHit = scamWords.find(v => textBlob.includes(v));
  if (scamHit) {
    score -= 100;
    scamRejectedCount++;
    riskFlags.push('High-risk phrase: ' + scamHit);
  }

  if (/send\s+.*crypto|deposit\s+.*claim|pay\s+.*claim/.test(textBlob)) {
    score -= 60;
    riskFlags.push('Potential pay/send-to-claim pattern.');
  }

  score = Math.max(0, Math.min(100, score));

  const acceptedNow = score >= MIN_SCORE;
  s.seen[dedupeKey] = {
    at: now,
    accepted: acceptedNow,
    score
  };

  if (!acceptedNow) {
    belowThresholdCount++;
    continue;
  }

  const cost = /\bfree\b|no cost|zero cost|learn/.test(textBlob)
    ? '€0 indicated — verify source'
    : 'Unknown — verify before action';

  const effort = /learn|quiz/.test(textBlob)
    ? '5–20 min'
    : (/quest|campaign|testnet/.test(textBlob) ? '10–60+ min' : 'Check source');

  let risk = 'MEDIUM';
  if (sourceVerification === 'OFFICIAL_EXCHANGE' && riskFlags.length === 0 && score >= 90) {
    risk = 'LOWER';
  } else if (
    ['KNOWN_QUEST_PLATFORM','REPUTABLE_MEDIA'].includes(sourceVerification)
    && riskFlags.length <= 1
  ) {
    risk = 'LOW-MEDIUM';
  }

  accepted.push({
    title,
    link,
    category: categoryOf(textBlob),
    score,
    source: sourceName || sourceHost || 'Discovery',
    sourceUrl: sourceUrl || null,
    sourceHost: sourceHost || null,
    linkHost: linkHost || null,
    sourceVerification,
    risk,
    riskFlags,
    scoreReasons,
    cost,
    effort,
    deadline: 'Check official source',
    network: null,
    estimatedReward: null,
    walletRequired: /connect wallet|wallet connection|sign message/.test(textBlob) ? 'Possibly' : 'Unknown',
    requirements: [],
    published: publishedRaw || null,
    foundAt: new Date(now).toISOString(),
    action: 'Open the source, verify the final domain, eligibility and terms. Never enter seed/private keys or send crypto just to qualify.'
  });
}

accepted.sort((a,b) => b.score - a.score);
const top = accepted.slice(0, 5);

const retained = s.recentAlerts.filter(a => {
  const t = Date.parse(a.foundAt || '');
  return Number.isFinite(t) && now - t < ALERT_TTL;
});

s.recentAlerts = uniq([...top, ...retained]).slice(0, 10);

for (const [k,v] of Object.entries(s.seen)) {
  const at = v && typeof v === 'object' ? Number(v.at) : Number(v);
  if (!Number.isFinite(at) || now - at > ACCEPTED_TTL) delete s.seen[k];
}

s.lastRunAt = new Date(now).toISOString();
s.lastRunSummary = {
  inputCount: input.length,
  newAlertCount: top.length,
  recentAlertCount: s.recentAlerts.length,
  minScore: MIN_SCORE,
  invalidCount,
  staleCount,
  duplicateCount,
  scamRejectedCount,
  belowThresholdCount,
  sourceErrorCount,
  officialSourceCount
};

return top.map(json => ({ json }));

