const s = $getWorkflowStaticData('global');
const recentAlerts = Array.isArray(s.recentAlerts) ? s.recentAlerts : [];
const seen = s.seen && typeof s.seen === 'object' ? s.seen : {};

return [{
  json: {
    ok: true,
    agent: 'HUNTER',
    version: '0.4',
    mode: 'WATCH_ONLY',
    minScore: 80,
    lastRunAt: s.lastRunAt || null,
    seenCount: Object.keys(seen).length,
    lastRunSummary: s.lastRunSummary || {
      inputCount: 0,
      newAlertCount: 0,
      recentAlertCount: recentAlerts.length,
      minScore: 80,
      invalidCount: 0,
      staleCount: 0,
      duplicateCount: 0,
      scamRejectedCount: 0,
      belowThresholdCount: 0,
      sourceErrorCount: 0,
      officialSourceCount: 0
    },
    lastAlerts: recentAlerts,
    safety: {
      walletMode: 'WATCH_ONLY_PUBLIC_ADDRESS',
      walletAccess: false,
      signing: false,
      transfers: false,
      trading: false,
      privateKeysStored: false
    }
  }
}];
